import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ATLAS - Runtime Foundation","description":"The current development state of the modular ATLAS framework.","frontmatter":{"title":"ATLAS - Runtime Foundation","description":"The current development state of the modular ATLAS framework.","date":"2026-08-02T00:00:00.000Z","author":"UGSo Software","tags":["ATLAS","TypeScript","Architecture"]},"headers":[],"relativePath":"en/blog/posts/atlas-runtime-foundation.md","filePath":"en/blog/posts/atlas-runtime-foundation.md","lastUpdated":1792840662000}'),r={name:"en/blog/posts/atlas-runtime-foundation.md"};function i(s,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="atlas-runtime-foundation" tabindex="-1">ATLAS - Runtime Foundation <a class="header-anchor" href="#atlas-runtime-foundation" aria-label="Permalink to &quot;ATLAS - Runtime Foundation&quot;">​</a></h1><p><strong>August 2, 2026 · ATLAS</strong></p><p>ATLAS is a modular TypeScript framework for reusable applications, plugins and Home-Assistant-oriented tools.</p><h2 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h2><p>The basic repository and documentation structure has been completed.</p><p>Already implemented:</p><ul><li>monorepo with <code>pnpm</code> workspaces</li><li>governance and architecture documents</li><li>event and contract layer</li><li>public event contracts</li><li><code>DefaultEventBus</code> reference implementation</li><li>tests for the fundamental components</li></ul><h2 id="next-sprint" tabindex="-1">Next Sprint <a class="header-anchor" href="#next-sprint" aria-label="Permalink to &quot;Next Sprint&quot;">​</a></h2><p>The next development step is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sprint G2.5.3 - Runtime Foundation</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The focus is on:</p><ul><li>service container</li><li>dependency injection</li><li>service descriptors</li><li>controlled dependency resolution</li><li>stable runtime contracts</li></ul><h2 id="long-term-goal" tabindex="-1">Long-Term Goal <a class="header-anchor" href="#long-term-goal" aria-label="Permalink to &quot;Long-Term Goal&quot;">​</a></h2><p>ATLAS is intended to create a shared technical foundation for several UGSo projects.</p><p>The <strong>Lovelace UV Card</strong> remains planned as a later project for UV index, protection status and visual Home Assistant dashboards.</p><h2 id="learn-more" tabindex="-1">Learn More <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn More&quot;">​</a></h2><p><a href="/en/projects/atlas/">Open the ATLAS project page</a></p>',17)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
